import{z as s,x as p,o as e,c as B,q as t,j as r,D as A,d as o,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"变形光学","description":"","frontmatter":{"title":"变形光学","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/anamorphic-projection.md","filePath":"litho/anamorphic-projection.md","lastUpdated":1791413859000}'),h={name:"litho/anamorphic-projection.md"};function m(d,a,N,c,D,C){const i=p("Mermaid");return e(),B("div",null,[a[2]||(a[2]=t('<h1 id="变形光学" tabindex="-1">变形光学 <a class="header-anchor" href="#变形光学" aria-label="Permalink to &quot;变形光学&quot;">​</a></h1><div class="epigraph"><p>High-NA 在狭缝向保持约 4×、在扫描向用约 8×，把掩模侧角度压回多层膜与阴影还能活的窗口。</p><footer>—— 据 van Schoot 等 ASML High-NA 公开光学论述</footer></div><p><a href="/litho/euv-oblique-shadow">上一课</a>把 0.33、各向同性 4× 的掩模主光线角钉在约 \\(6^\\circ\\)，并指出再抬 NA 会把 CRA 与掩模 NA 一起打穿多层布拉格。缺口是：硅片侧仍要 0.55 的分辨率，掩模侧却不能按 \\(0.55/4\\) 线性放大角度。本课钉变形光学（anamorphic projection）。半场如何拼大芯片，在 <a href="/litho/asml-high-na">High-NA 整机</a> 与后课拼接里展开；氢污染控制从<a href="/litho/euv-hydrogen-dgl">下一课</a>接回量产腔。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>掩模侧数值孔径是硅片 NA 除以倍率。各向同性 4×、NA 0.55 给出掩模 NA \\(\\approx 0.138\\)，主光线角和入射角范围让 Mo/Si 峰值、偏振分裂和吸收体阴影同时越界；6 英寸版也放不下光瞳。镜子口径按 NA 涨，POB 包络成为机械墙。</p><p>需要不对称倍率：对阴影和多层最敏感的扫描方向提高倍率、减小掩模角；狭缝方向保持约 4×，以便 26 mm 狭缝宽度与工件台速度比仍与 NXE 相容。这就是 van Schoot 公开的 High-NA 变形方案，不是把 0.33 物镜「开光圈」。</p><p><span class="marginnote">直觉类比：变形投影很像电影院的变形宽银幕镜头——拍摄时把画面横向压扁收进胶片，放映时再拉开。光刻里『拍』落在掩模上，『放』发生在曝光那一瞬，两个方向比例尺不同。</span></p><h3 id="_4×-8×-各保护什么" tabindex="-1">4×/8× 各保护什么 <a class="header-anchor" href="#_4×-8×-各保护什么" aria-label="Permalink to &quot;4×/8× 各保护什么&quot;">​</a></h3><p>狭缝向约 4×：26 mm 狭缝宽度不变、工件台扫描速度与 NXE 相容。扫描向约 8×：掩模上的场更瘦，角谱回到多层能给高反、吸收体能给可接受阴影的区间，6 英寸空白版装得下光瞳。硅片上场在扫描向减半，约 26 mm × 16.5 mm，这是几何推论，不是任意切场。</p><p><span class="marginnote">变形不是「硅片上 X 与 Y 分辨率不同」。硅片侧 NA 仍以 0.55 为目标成像；不对称的是掩模到硅片的几何倍率。不要写成 EXE 只能做椭圆孔。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>蔡司为 EXE 做更大口径的强非球面变形投影组，波前计量按各向异性光瞳来。照明、掩模三维和 OPC 必须用两套倍率：同一条线在扫描向与狭缝向的掩模 CD、阴影和 MEEF 不同。光瞳填充在两方向不对称，SMO 自由度增加，旧的各向同性 4× 模型不能签字。</p><p>场几何：26 mm（狭缝）× 16.5 mm（扫描）。超过半场的 die 要两次曝光拼接，套刻与剂量连续性是下一层课的缺口；本课只把「为什么必须半场」接到变形倍率上。pellicle 角透过率与热也要按新 CRA 重写，不在本课展开膜。</p><h3 id="分辨率从哪里来" tabindex="-1">分辨率从哪里来 <a class="header-anchor" href="#分辨率从哪里来" aria-label="Permalink to &quot;分辨率从哪里来&quot;">​</a></h3> \\[\\frac{\\lambda/\\mathrm{NA}_{0.55}}{\\lambda/\\mathrm{NA}_{0.33}} = \\frac{0.33}{0.55}\\approx 0.60, \\]<p>特征尺寸约缩到 0.33 系统的 60%。卖点是把原需 EUV 双重的节距拉回单次。焦深按 \\(\\lambda/\\mathrm{NA}^2\\) 再变薄，随机效应在更小孔上可能更严——变形光学解决的是掩模角，不是泊松统计。</p>',16)),(e(),r(n,null,{default:A(()=>[l(i,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20NA%5B%22%E7%A1%85%E7%89%87%20NA%200.55%22%5D%20--%3E%20AN%5B%22%E5%8F%98%E5%BD%A2%204%C3%97%20%E7%8B%AD%E7%BC%9D%20%2F%208%C3%97%20%E6%89%AB%E6%8F%8F%22%5D%0A%20%20AN%20--%3E%20ANG%5B%22%E6%8E%A9%E6%A8%A1%E4%BE%A7%E8%A7%92%E5%BA%A6%E5%8F%AF%E6%8E%A5%E5%8F%97%22%5D%0A%20%20AN%20--%3E%20HF%5B%22%E5%8D%8A%E5%9C%BA%2026%C3%9716.5%20mm%22%5D%0A%20%20ANG%20--%3E%20ML%5B%22%E5%A4%9A%E5%B1%82%E8%86%9C%E4%B8%8E%E9%98%B4%E5%BD%B1%E7%AA%97%E5%8F%A3%22%5D%0A%20%20HF%20--%3E%20ST%5B%22%E5%A4%A7%20die%20%E6%8B%BC%E6%8E%A5%20%E5%90%8E%E8%AF%BE%22%5D%0A"})]),fallback:A(()=>[...a[0]||(a[0]=[o(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[o("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"倍率提高的方向上，掩模 NA 减半相对各向同性 4× 的 0.55 方案，CRA 被压回与 0.33 平台可类比的工作区（van Schoot 公开论述的核心几何）。多层周期与吸收体厚度因此不必为 0.55 重做一套「更厚、更斜」的不可能膜系。代价是投影镜子更大、更非球面，透过率与热负荷不比 NXE 宽松，仍依赖高功率 LPP。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"掩模 NA = 硅片 NA ÷ 倍率：0.55 ÷ 4 ≈ 0.138，0.55 ÷ 8 ≈ 0.069。扫描向把倍率翻倍，掩模侧角度几乎砍半——这正是 Mo/Si 多层膜还愿意给出高反射的入射角区间。")],-1)),(e(),r(n,null,{default:A(()=>[l(i,{id:"mermaid-54",class:"mermaid",graph:"flowchart%20TD%0A%20%20FIX%5B%22%E5%8F%98%E5%BD%A2%E5%8F%AA%E8%A7%A3%E5%86%B3%3A%20%E6%8E%A9%E6%A8%A1%E4%BE%A7%E8%A7%92%E5%BA%A6%E4%B8%8E%E7%89%88%E9%9D%A2%22%5D%20--%3E%20DOF%5B%22%E6%B2%A1%E8%A7%A3%E5%86%B3%3A%20DOF%20%E6%8C%89%20%CE%BB%2FNA%C2%B2%20%E5%8F%98%E8%96%84%22%5D%0A%20%20FIX%20--%3E%20STO%5B%22%E6%B2%A1%E8%A7%A3%E5%86%B3%3A%20%E6%9B%B4%E5%B0%8F%E5%AD%94%E5%85%89%E5%AD%90%E6%9B%B4%E5%B0%91%22%5D%0A%20%20DOF%20--%3E%20FOC%5B%22%E8%B0%83%E7%84%A6%20%2F%20%E5%B9%B3%E6%95%B4%E5%BA%A6%E9%A2%84%E7%AE%97%E6%9B%B4%E7%B4%A7%22%5D%0A%20%20STO%20--%3E%20DOS%5B%22%E5%89%82%E9%87%8F%E4%B8%8E%E8%83%B6%E5%8E%8B%E5%8A%9B%E4%B8%8A%E5%8D%87%22%5D%0A%20%20FOC%20--%3E%20BAL%5B%22%E5%8D%95%E6%AC%A1%E7%9C%81%E5%8F%8C%E9%87%8D%20vs%20%E8%BF%99%E4%BA%9B%E4%BB%A3%E4%BB%B7%20%E4%B8%80%E8%B5%B7%E8%BF%9B%E8%B4%A6%22%5D%0A%20%20DOS%20--%3E%20BAL%0A"})]),fallback:A(()=>[...a[1]||(a[1]=[o(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p>成像 TCC 在两方向用不同缩放。SRAF、ILT 曲边在 8× 方向的掩模规则与 4× 方向不同，MRC 要分轴。计算光刻资格认证按平台拆开，不能把 NXE OPC 改个 NA 数字交差。</p><p><span class="marginnote">EXE 与 NXE 不要混名。NXE 是各向同性 4×、全场、NA 0.33；EXE 是变形 4×/8×、半场、NA 0.55。说「ASML 的 EUV 倍率」而不标轴，在 2026 年会把阴影模型写错。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写未公布的镜面张数，不编造 EXE 的 wph。半场拼接的套刻算法留给机台课序。氢 DGL 不因变形而取消，下一课回到污染。出处：van Schoot High-NA 公开论文与 ASML/Zeiss High-NA 材料；场尺寸 26 × 16.5 mm、4×/8×、NA 0.55 是公开合同。</p><p>也不要把变形当成偏振魔法。大 NA 的矢量效应仍在硅片侧；变形只是不让掩模侧先死。</p><p><span class="marginnote">常见误区：『分辨率缩到 60%，EUV 双重就全省了』。收益只在特定节距与取向上成立；焦深变薄、光子散粒噪声、半场拼接都要另记账——是不是净赚，按层算，不是按平台算。</span></p><p><span class="marginnote">8× 方向掩模 CD 更大，写版与检测的纳米误差缩到硅片时除以 8，对那一轴的掩模误差预算更松；4× 轴仍按老规矩。这是分轴 MEEF，不是「掩模突然容易做了」。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>各向同性 4× 无法同时承载 NA 0.55 的掩模角与 6 英寸版。</li><li>变形光学：狭缝向约 4×、扫描向约 8×，压低 CRA 与掩模 NA。</li><li>硅片场约 26 × 16.5 mm；大芯片拼接是几何代价。</li><li>光学特征尺寸约缩到 0.33 的 60%；焦深与随机另记账。</li><li>OPC/SMO/M3D 必须分轴；下一课接回氢气锁与污染。</li><li>出处：van Schoot 等 High-NA 公开光学；ASML / Zeiss。</li></ul>',9))])}const f=s(h,[["render",m]]);export{F as __pageData,f as default};
